import {Zap, LayoutDashboard, Trophy, Users, Layers, Columns3, MessageSquare, BookOpen, CalendarDays, Map, Building2, Send, Bell, Settings, Shield, Gavel, ChevronRight, ArrowUpRight, ArrowRight, Plus, Check, Clock, LogOut, X, Search, Github, CheckCircle2, Circle, ExternalLink, Menu, AlertTriangle, FileText, Code2, Target, Sparkles, BarChart3, GraduationCap, Flag, User, Download, RefreshCw, CheckCheck, Copy} from 'lucide-react';
