let csrf='';
async function api(path,method='GET',data){
  if(method!=='GET'&&!csrf){ const r=await fetch('/api/auth/csrf',{credentials:'include'}); csrf=(await r.json()).token; }
  const options={method,credentials:'include',headers:{}};
  if(method!=='GET')options.headers['X-CSRFToken']=csrf;
  if(data instanceof FormData) options.body=data;
  else if(data!==undefined){options.headers['Content-Type']='application/json';options.body=JSON.stringify(data);}
  const r=await fetch('/api'+path,options); const d=await r.json().catch(()=>({error:'Некорректный ответ сервера'}));
  if(!r.ok){if(d.code==='csrf')csrf=''; throw new Error(d.error||'Не удалось выполнить запрос');}return d;
}
const fmt=(d,opts={})=>d?new Date(d).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',...opts}):'Не указан';
const difficulties={easy:'Лёгкий',medium:'Средний',hard:'Сложный'};const rewards={easy:70,medium:150,hard:240};
const statuses={upcoming:'Предстоящий',active:'В процессе',review:'На проверке',completed:'Завершён'};
const taskStatus={todo:'К выполнению',doing:'В работе',review:'На проверке',done:'Выполнено'};
const appealStatuses={sent:'Отправлена',review:'На рассмотрении',clarification:'Требуется уточнение',accepted:'Принята',rejected:'Отклонена'};
const roleNames={mentor:'Ментор',admin:'Администратор',jury:'Жюри',organizer:'Организатор',participant:'Участник'};
const nav=[['home','Главная',LayoutDashboard],['mentor','Мои команды',GraduationCap],['city','Город команд',Building2],['hackathons','Хакатоны',Trophy],['team','Моя команда',Users],['cases','Кейсы',Layers],['kanban','Доска задач',Columns3],['chat','Командный чат',MessageSquare],['materials','Обучение',BookOpen],['schedule','Расписание',CalendarDays],['roadmap','Дорожная карта',Map],['submission','Сдача проекта',Send]];
const titles=Object.fromEntries([...nav.map(([k,t])=>[k,t]),['ranking','Результаты хакатона'],['ratings','Личный рейтинг'],['profile','Мой профиль'],['settings','Настройки'],['notifications','Уведомления'],['organizer','Управление хакатоном'],['admin','Администрирование'],['jury','Кабинет жюри'],['peer','Peer review'],['appeals','Апелляции'],['orgchat','Чат с организатором'],['codecheck','CodeCheck'],['expert','Экспертная обратная связь']]);
function Button({children,onClick,variant='',className='',...props}){return <button className={'button '+variant+' '+className} onClick={onClick} {...props}>{children}</button>}
function Empty({icon:Icon=Layers,title='Пока здесь пусто',text:description,children}){return <div className="empty"><Icon size={34}/><h3>{title}</h3><p>{description}</p>{children}</div>}
function Badge({children,tone=''}){return <span className={'badge '+tone}>{children}</span>}
function Avatar({user,className='',zoom=true}){const [open,setOpen]=useState(false);useEffect(()=>{const fn=e=>{if(e.key==='Escape')setOpen(false)};if(open)window.addEventListener('keydown',fn);return()=>window.removeEventListener('keydown',fn)},[open]);return <><span className={'avatar '+className} onClick={e=>{if(user.avatar&&zoom){e.stopPropagation();setOpen(true)}}}>{user.avatar?<img src={user.avatar} alt={user.nickname}/>:user.nickname.slice(0,1)}</span>{open&&<div className="modal-backdrop" role="dialog" aria-modal="true" aria-label="Аватар" onClick={e=>{e.stopPropagation();if(e.target===e.currentTarget)setOpen(false)}}><div className="avatar-preview"><button aria-label="Закрыть" onClick={()=>setOpen(false)}>✕</button><img src={user.avatar} alt={user.nickname}/></div></div>}</>}
function HackathonImage({event,className=''}){return <img className={'hackathon-image '+className} src={event?.cover||'/hackathons/default.svg'} alt="" loading="lazy" decoding="async" onError={e=>{if(!e.currentTarget.src.endsWith('/hackathons/default.svg'))e.currentTarget.src='/hackathons/default.svg'}}/>}
function SidebarAccount({user,label,onProfile,onLogout}){return <div className="sidebar-bottom"><button className="user-card" onClick={onProfile}><Avatar user={user} zoom={false}/><span><strong>{user.nickname}</strong><small>{label}</small></span><Settings size={17}/></button><button className="sidebar-logout" onClick={onLogout} aria-label="Выйти из аккаунта"><LogOut size={16}/><span>Выйти из аккаунта</span></button></div>}
function Progress({value=0}){return <div className="progress"><i style={{width:value+'%'}}/></div>}
function resolvePage(requested,user){if(user?.role==='mentor'&&!['home','mentor','materials','schedule','profile','settings','notifications'].includes(requested||'home'))return 'mentor';return !requested||requested==='dashboard'?'home':requested}
function Welcome(c){return <section className="panel home-empty"><span className="square-icon"><Trophy size={24}/></span><h2>{c.loading?'Загружаем хакатон…':'Выбери, над чем работать'}</h2><p>{c.loading?'Собираем задачи, сроки и команду.':'В каталоге можно найти хакатон и зарегистрироваться на него. После этого здесь появится твой рабочий стол.'}</p>{!c.loading&&<Button onClick={()=>c.go('hackathons')}>Открыть хакатоны<ArrowRight size={16}/></Button>}</section>}
function StaffHome(c){return <section className="panel staff-home"><h2>Управление хакатоном</h2><p>Выбери мероприятие и открой кабинет.</p><div className="panel-actions">{c.user.role==='admin'&&<Button onClick={()=>c.go('admin')}><Shield size={16}/>Администрирование</Button>}{(c.user.role==='admin'||c.user.role==='organizer'||c.h?.organizer)&&<Button variant="secondary" onClick={()=>c.go('organizer')}><BarChart3 size={16}/>Управление хакатоном</Button>}{(c.h?.jury||c.events.some(e=>e.jury))&&<Button variant="secondary" onClick={()=>c.go('jury')}><Gavel size={16}/>Кабинет жюри</Button>}<Button variant="ghost" onClick={()=>c.go('hackathons')}>Все хакатоны<ArrowRight size={16}/></Button></div></section>}
function App(){
 const [user,setUser]=useState(null),[boot,setBoot]=useState(true),[requestedPage,setPage]=useState(location.hash.slice(1)||'home'),[events,setEvents]=useState([]),[hid,setHid]=useState(Number(localStorage.getItem('hackflow-event'))||0),[h,setH]=useState(null),[eventLoading,setEventLoading]=useState(false),[cases,setCases]=useState([]),[criteria,setCriteria]=useState([]),[team,setTeam]=useState(null),[notes,setNotes]=useState([]),[toast,setToast]=useState(null),[modal,setModal]=useState(null),[busy,setBusy]=useState(false),[mobile,setMobile]=useState(false),[revision,setRevision]=useState(0),[theme,setTheme]=useState(localStorage.getItem('hackflow-theme')||'holiday'),[snowEnabled,setSnowEnabled]=useState(localStorage.getItem('hackflow-snow')!=='off');
 const page=resolvePage(requestedPage,user);
 useEffect(()=>{if(user&&requestedPage!==page){history.replaceState({},'',location.pathname+location.search+'#'+page);setPage(page)}},[requestedPage,page,user?.id,user?.participant]);
 const go=(p)=>{location.hash=p;setPage(p);setMobile(false)};
 const flash=(message,error=false)=>{setToast({message,error});setTimeout(()=>setToast(null),6500)};
 const run=async(fn)=>{setBusy(true);try{return await fn()}catch(e){flash(e.message,true);return null}finally{setBusy(false)}};
 const refresh=()=>setRevision(x=>x+1);
 const selectTheme=async value=>(await run(async()=>{const r=await api('/profile','PATCH',{theme:value});setTheme(r.user.theme||value);setUser(r.user);return true}))===true;
 useEffect(()=>{const fn=()=>setPage(location.hash.slice(1)||'home');window.addEventListener('hashchange',fn);return()=>window.removeEventListener('hashchange',fn)},[]);
 useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('hackflow-theme',theme);document.querySelector('meta[name="theme-color"]')?.setAttribute('content',getComputedStyle(document.documentElement).getPropertyValue('--bg').trim())},[theme]);
 useEffect(()=>{localStorage.setItem('hackflow-snow',snowEnabled?'on':'off')},[snowEnabled]);
 useEffect(()=>{api('/auth/me').then(d=>{setUser(d.user);setTheme(d.user.theme||'holiday')}).catch(()=>{}).finally(()=>setBoot(false))},[]);
 useEffect(()=>{if(!user)return;api('/hackathons').then(d=>{setEvents(d.items);if(!d.items.some(e=>e.id===hid)){const preferred=d.items.find(e=>e.admitted&&e.status==='active')||d.items.find(e=>e.admitted)||d.items[0];setHid(preferred?.id||0)}}).catch(e=>flash(e.message,true));api('/notifications').then(d=>setNotes(d.items)).catch(()=>{})},[user?.id,revision]);
 useEffect(()=>{let active=true;setH(null);setTeam(null);setCases([]);setCriteria([]);const selected=events.find(e=>e.id===hid);if(!user||!hid||!selected?.admitted){setEventLoading(false);return}setEventLoading(true);localStorage.setItem('hackflow-event',hid);api('/hackathons/'+hid).then(async d=>{if(!active)return;setCases(d.cases);setCriteria(d.criteria);if(d.hackathon.team_id){const t=await api('/teams/'+d.hackathon.team_id);if(active)setTeam({...t.team,submission:t.submission,requests:t.requests})}if(active)setH(d.hackathon)}).catch(e=>{if(active)flash(e.message,true)}).finally(()=>{if(active)setEventLoading(false)});return()=>{active=false}},[hid,user?.id,revision,events]);
 useEffect(()=>{if(!user)return;const p=new URLSearchParams(location.search);if(p.has('invite'))run(async()=>{await api('/jury-invitations/accept','POST',{token:p.get('invite')});history.replaceState({},'',location.pathname+location.hash);setUser((await api('/auth/me')).user);flash('Приглашение жюри принято');refresh()})},[user?.id]);
 useEffect(()=>{if(!user)return;const timer=setInterval(()=>api('/notifications').then(d=>setNotes(d.items)).catch(()=>{}),30000);return()=>clearInterval(timer)},[user?.id]);
 const form=(title,fields,submit,initial={},help='')=>setModal({title,fields,submit,initial,help});
 const context={user,h,hid,team,cases,criteria,go,api,run,flash,refresh,form,busy,revision,events,setHid};
 if(boot)return <div className="loading"><Zap size={40}/><p>Загружаем рабочее пространство…</p></div>;
 if(!user)return <><Snowfall enabled={theme==='holiday'&&snowEnabled}/><Auth onLogin={u=>{csrf='';setUser(u);setTheme(u.theme||'holiday');go('home');refresh()}} run={run} busy={busy} toast={toast}/></>;
 const isOrg=h?.organizer, isJury=user.role==='jury'||h?.jury||events.some(e=>e.jury);const staff=user.participant===false;const staffPages=['mentor','materials','schedule','home','city','hackathons','organizer','jury','profile','settings','notifications','admin','ranking','orgchat'];
 return <div className="app"><Snowfall enabled={theme==='holiday'&&snowEnabled}/>
 <aside className={'sidebar '+(mobile?'shown':'')}><a href="#home" className="brand"><span className="brand-icon"><Zap size={22} fill="currentColor"/></span>hack<span>flow</span><span className="brand-dot">®</span><HolidayHat enabled={theme==='holiday'}/></a><div className="workspace-label">РАБОЧЕЕ ПРОСТРАНСТВО</div><div className="event-switch"><span className="event-thumbnail"><HackathonImage event={events.find(e=>e.id===hid)}/></span><div><strong>{events.find(e=>e.id===hid)?.title||'Выберите хакатон'}</strong><small>{events.find(e=>e.id===hid)?.is_demo?'Демонстрационный хакатон':'Студенческий хакатон'}</small></div><ChevronRight size={15}/><select aria-label="Текущий хакатон" value={hid} onChange={e=>setHid(Number(e.target.value))}>{events.filter(e=>user.participant!==false||e.organizer||e.jury||e.mentor||user.role==='admin').map(e=><option value={e.id} key={e.id}>{e.title}</option>)}</select></div>
 <nav aria-label="Основные разделы">{nav.filter(([key])=>user.role==='mentor'?['home','mentor','materials','schedule'].includes(key):key==='mentor'?false:!staff||['home','hackathons'].includes(key)||key==='city'&&(isOrg||user.role==='admin'||h?.results_published)).map(([key,title,Icon])=><button key={key} className={'nav-item '+(page===key?'active':'')} onClick={()=>go(key)}><Icon size={18}/><span>{title}</span></button>)}</nav>
 {user.role!=='mentor'&&<details className="secondary-nav" open={['ranking','peer','expert','orgchat','appeals'].includes(page)}><summary><span className="secondary-nav-title"><Trophy size={16}/><span>Итоги хакатона</span></span><ChevronRight className="secondary-nav-chevron" size={14}/></summary><nav aria-label="Итоги хакатона">{[['ranking','Рейтинг команд',Trophy],['peer','Peer review',CheckCheck],['expert','Отзывы экспертов',GraduationCap],['orgchat','Чат с организатором',MessageSquare],['appeals','Апелляции',Flag]].filter(([key])=>!staff||['ranking','orgchat'].includes(key)).map(([key,title,Icon])=><button key={key} className={'nav-item '+(page===key?'active':'')} onClick={()=>go(key)}><Icon size={18}/><span>{title}</span></button>)}</nav></details>}
 {(isOrg||isJury||user.role==='admin'||user.role==='organizer')&&<><div className="nav-section">УПРАВЛЕНИЕ</div>{(isOrg||user.role==='organizer'||user.role==='admin')&&<button className={'nav-item '+(page==='organizer'?'active':'')} onClick={()=>go('organizer')}><BarChart3 size={18}/>Кабинет организатора</button>}{isJury&&<button className="nav-item" onClick={()=>go('jury')}><Gavel size={18}/>Кабинет жюри</button>}{user.role==='admin'&&<button className="nav-item" onClick={()=>go('admin')}><Shield size={18}/>Администрирование</button>}</>}
 <SidebarAccount user={user} label={user.is_owner?'Главный администратор':isJury?'Жюри':roleNames[user.role]} onProfile={()=>go('profile')} onLogout={()=>run(async()=>{await api('/auth/logout','POST',{});setUser(null);csrf=''})}/></aside>
 <div className="main-shell"><header className={"topbar "+(theme==='holiday'?'festive-header':'')}><WinterGarland enabled={theme==='holiday'}/><button className="icon-button mobile-menu" onClick={()=>setMobile(!mobile)} aria-label="Открыть меню"><Menu/></button><div className="breadcrumb">Рабочее пространство <ChevronRight size={14}/><span>{titles[page]||'Главная'}</span></div><div className="top-actions"><ThemeSwitcher theme={theme} onSelect={selectTheme} busy={busy} snowEnabled={snowEnabled} onSnowChange={setSnowEnabled}/><span className="today">{new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}</span><button className="icon-button notification-button" aria-label="Уведомления" onClick={()=>go('notifications')}><Bell size={19}/>{notes.some(n=>!n.read)&&<i/>}</button><button className="icon-button" onClick={()=>go('profile')} aria-label="Мой профиль"><Avatar user={user} className="small" zoom={false}/></button></div></header>
 <main key={hid}><div className={"page-heading "+(page==='home'?'home-heading':'')}><div><h1>{page==='home'?(staff?'Рабочий стол':h?.title||'Твоё пространство'):titles[page]||'HackFlow'}</h1><p>{page==='home'?'':page==='dashboard'?'':page==='kanban'?'Задачи и прогресс команды.':page==='materials'?'Материалы хакатона.':page==='schedule'?'События и сроки.':''}</p></div>{page==='home'&&h&&<Badge tone="green"><span className="live-dot"/>{statuses[h?.status]||'Добро пожаловать'}</Badge>}{page==='kanban'&&team&&<Button onClick={()=>form('Новая задача',taskFields(team),d=>run(async()=>{await api(`/teams/${team.id}/tasks`,'POST',d);refresh();setModal(null)}))}><Plus size={16}/>Создать задачу</Button>}</div>
 {page==='home'?(user.role==='mentor'?<MentorWorkspace c={context}/>:staff?<StaffHome {...context}/>:h?<Dashboard {...context}/>:<Welcome {...context} loading={eventLoading}/>):staff&&!staffPages.includes(page)?<Empty title="Рабочее пространство сотрудника"><Button onClick={()=>go(user.role==='admin'?'admin':user.role==='organizer'?'organizer':'jury')}>Открыть кабинет</Button></Empty>:page==='mentor'?<MentorWorkspace c={context}/>:page==='hackathons'?<Catalog {...context}/>:page==='profile'?<Profile {...context}/>:page==='settings'?<SettingsPage {...context} setUser={setUser}/>:page==='notifications'?<Notifications {...context} notes={notes}/>:page==='ratings'?<Ratings {...context}/>:page==='admin'?<Admin {...context} setUser={setUser}/>:page==='expert'?<Expert {...context}/>:page==='organizer'&&!h?<CreateHackathon {...context}/>:!h?<Empty title="Выберите доступный хакатон" text="Зарегистрируйтесь на мероприятие в каталоге."><Button onClick={()=>go('hackathons')}>Открыть каталог</Button></Empty>:
 page==='city'?<TeamCity {...context}/>:page==='dashboard'?<Dashboard {...context}/>:page==='team'?<TeamPage {...context}/>:page==='cases'?<Cases {...context}/>:page==='kanban'?<Board {...context}/>:page==='chat'||page==='orgchat'?<Chat {...context} channel={page==='orgchat'?'organizer':'team'}/>:page==='materials'?<Materials {...context}/>:page==='schedule'?<SchedulePage {...context}/>:page==='roadmap'?<Roadmap {...context}/>:page==='submission'?<SubmissionPage {...context}/>:page==='organizer'?<Organizer {...context}/>:page==='jury'?<Jury {...context}/>:page==='ranking'?<Ranking {...context}/>:page==='peer'?<Peer {...context}/>:page==='appeals'?<Appeals {...context}/>:page==='codecheck'?<CodeCheck {...context}/>:page==='expert'?<Expert {...context}/>:<Dashboard {...context}/>}
 </main></div>
 {toast&&<div role="status" className={'toast '+(toast.error?'error':'')}><span>{toast.message}</span><button onClick={()=>setToast(null)} aria-label="Закрыть"><X size={16}/></button></div>}
 {modal&&<FormModal {...modal} close={()=>setModal(null)} busy={busy}/>}

 </div>
}
function Auth({onLogin,run,busy,toast}){
 const token=new URLSearchParams(location.search).get('reset');const [mode,setMode]=useState(token?'reset':'login'),[d,setD]=useState({}),[message,setMessage]=useState('');
 const submit=e=>{e.preventDefault();run(async()=>{if(mode==='forgot'){const r=await api('/auth/forgot','POST',d);setMessage(r.message);return}if(mode==='reset'){await api('/auth/reset','POST',{...d,token});history.replaceState({},'',location.pathname);setMode('login');setMessage('Пароль изменён. Войдите в аккаунт.');return}const r=await api('/auth/'+(mode==='register'?'register':'login'),'POST',d);onLogin(r.user)})};
 return <div className="auth-layout"><section className="auth-story"><a className="brand" href="#"><span className="brand-icon"><Zap fill="currentColor"/></span>hack<span>flow</span></a><div className="auth-intro"><span className="auth-symbol" aria-hidden="true"><Layers size={52} strokeWidth={1.1}/></span><h1>Командная работа<br/>на хакатоне.</h1><p>Собирай команду, планируй задачи и готовь проект.</p><div className="auth-features"><span><Columns3 size={16}/>Задачи</span><span><MessageSquare size={16}/>Обсуждения</span><span><BookOpen size={16}/>Материалы</span></div></div></section><section className="auth-form"><div className="auth-box"><h2>{mode==='register'?'Создать аккаунт':mode==='forgot'?'Восстановление доступа':mode==='reset'?'Новый пароль':'С возвращением'}</h2><p>{mode==='register'?'Заполни данные для регистрации.':mode==='login'?'Войди, чтобы продолжить работу.':'Укажи данные для восстановления доступа.'}</p>{['login','register'].includes(mode)&&<div className="tabs"><button className={mode==='login'?'selected':''} onClick={()=>{setMode('login');setMessage('')}}>Вход</button><button className={mode==='register'?'selected':''} onClick={()=>{setMode('register');setMessage('')}}>Регистрация</button></div>}<form onSubmit={submit}>{mode==='register'&&<label>Никнейм<input required maxLength="64" autoComplete="nickname" value={d.nickname||''} onChange={e=>setD({...d,nickname:e.target.value})} placeholder="Как к тебе обращаться?"/></label>}{mode!=='reset'&&<label>Email<input type="email" required autoComplete="email" value={d.email||''} onChange={e=>setD({...d,email:e.target.value})} placeholder="you@example.com"/></label>}{mode!=='forgot'&&<label>Пароль<input type="password" required minLength={mode==='login'?1:10} autoComplete={mode==='login'?'current-password':'new-password'} value={d.password||''} onChange={e=>setD({...d,password:e.target.value})} placeholder={mode==='login'?'Введите пароль':'Минимум 10 символов'}/></label>}{mode==='login'&&<button type="button" className="text-button forgot" onClick={()=>setMode('forgot')}>Не помню пароль</button>}<Button className="full" disabled={busy}>{busy?'Подождите…':mode==='register'?'Создать аккаунт':mode==='forgot'?'Получить ссылку':mode==='reset'?'Сохранить пароль':'Войти'}<ArrowRight size={17}/></Button></form>{message&&<p className="notice">{message}</p>}{toast&&<p role="alert" className="error-text">{toast.message}</p>}{['forgot','reset'].includes(mode)&&<button className="text-button" onClick={()=>setMode('login')}>Вернуться ко входу</button>}<div className="demo-info"><Shield size={20}/><p>Закрытый хакатон?<br/><span>Регистрация аккаунта не заменяет допуск организатора.</span></p></div></div><small className="auth-copyright">HackFlow</small></section></div>
}
function FormModal({title,fields,submit,initial={},help,close,busy}){const [d,setD]=useState(initial);return <div className="modal-backdrop" onClick={e=>e.target===e.currentTarget&&close()}><section className="modal" role="dialog" aria-modal="true" aria-label={title}><div className="section-title"><h2>{title}</h2><button className="icon-button" aria-label="Закрыть" onClick={close}><X/></button></div>{help&&<p className="notice">{help}</p>}<form onSubmit={e=>{e.preventDefault();submit(d).then?.(result=>{if(result!==null)close()})}}>{fields.map(f=><label key={f.key}>{f.label}{f.type==='textarea'?<textarea rows="4" required={!f.optional} value={d[f.key]??''} onChange={e=>setD({...d,[f.key]:e.target.value})}/>:f.options?<select required={!f.optional} value={d[f.key]??''} onChange={e=>setD({...d,[f.key]:e.target.value})}><option value="">Выберите…</option>{f.options.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select>:<input type={f.type||'text'} required={!f.optional} min={f.min} max={f.max} value={d[f.key]??''} onChange={e=>setD({...d,[f.key]:f.type==='number'?Number(e.target.value):e.target.value})}/>}</label>)}<div className="form-actions"><Button type="button" variant="secondary" onClick={close}>Отмена</Button><Button disabled={busy}>{busy?'Сохраняем…':'Сохранить'}</Button></div></form></section></div>}
function useData(path,revision=0){const [data,setData]=useState(null),[error,setError]=useState('');useEffect(()=>{let active=true;setData(null);setError('');if(path)api(path).then(d=>active&&setData(d)).catch(e=>active&&setError(e.message));return()=>{active=false}},[path,revision]);return [data,error]}
