function CaseCard({item:x,index=0,c}){return <section className={'panel case-card case-accent-'+index%3}><div className="section-title"><Badge>{x.company}</Badge></div><h2>{x.title}</h2><p className="case-preview">{x.description}</p><details className="case-details"><summary>Подробнее<ChevronRight size={15}/></summary><div className="case-full"><p>{x.description}</p>{x.requirements&&<><h4>Требования</h4><p>{x.requirements}</p></>}{x.expected&&<><h4>Результат</h4><p>{x.expected}</p></>}{x.url&&<a href={x.url} target="_blank" rel="noreferrer" className="text-button">Материалы<ExternalLink size={14}/></a>}</div></details><div className="case-actions">{c.team?.case_id===x.id?<Badge tone="green"><Check size={14}/>Выбран</Badge>:c.team?.captain_id===c.user.id&&<Button onClick={()=>c.run(async()=>{await api(`/teams/${c.team.id}`,'PATCH',{case_id:x.id});c.refresh();c.flash('Кейс выбран')} )}>Выбрать кейс<ArrowRight size={15}/></Button>}</div></section>}
