 return <><DataError error={error}/><div className="board-toolbar"><span className="member-pill"><span className="team-symbol board-team-symbol">{team.name[0]}</span>{team.name}</span><div className="board-completion"><span>{error?'Задачи не загружены':data?`Выполнено ${done} из ${tasks.length}`:'Загружаем задачи…'}</span><Progress value={tasks.length?done/tasks.length*100:0}/></div><span className="board-event-thumb"><HackathonImage event={c.h}/></span></div><div className="board">{Object.entries(taskStatus).map(([key,label])=>{const column=tasks.filter(t=>t.status===key);return <section className={'board-column '+key} key={key} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(id)move(Number(id),key)}}><div className="column-head"><span className="status-dot"/><h3>{label}</h3><span>{data?column.length:'—'}</span></div>{column.map(t=>{const assignee=t.assignee_id===c.user.id?c.user:team.members.find(m=>m.id===t.assignee_id)||{nickname:'Не назначен'};return <article className="task-card" key={t.id} draggable onDragStart={e=>e.dataTransfer.setData('text/plain',String(t.id))}><small>HF-{String(t.id).padStart(3,'0')}</small><h4>{t.title}</h4>{t.description&&<p>{t.description}</p>}<div className="task-deadline"><Clock size={12}/>{t.deadline?fmt(t.deadline):'Без срока'}</div><div className="task-card-bottom"><select aria-label={'Статус задачи '+t.title} title={taskStatus[t.status]} value={t.status} onChange={e=>move(t.id,e.target.value)}>{Object.entries(taskStatus).map(([v,l])=><option value={v} key={v}>{l}</option>)}</select><span className="task-assignee" title={assignee.nickname}><Avatar user={assignee} className="tiny"/><span>{assignee.nickname}</span></span><div className="task-card-actions"><button className="icon-button" aria-label="Изменить задачу" onClick={()=>c.form('Изменить задачу',taskFields(team),d=>c.run(async()=>{await api(`/tasks/${t.id}`,'PATCH',d);c.refresh()}),{...t,deadline:t.deadline?.slice(0,16)})}><Settings size={13}/></button><button className="icon-button" aria-label="Удалить задачу" onClick={()=>c.form('Удалить задачу',[],()=>c.run(async()=>{await api(`/tasks/${t.id}`,'DELETE');c.refresh()}),{},t.title)}><X size={13}/></button></div></div></article>})}{data&&!error&&!column.length&&<BoardEmpty status={key} onCreate={create}/>}</section>})}</div></>
